using System;using System.IO;
public delegate void MapLoaderAction();public class MapLoaderContainer{public string id;}public static class SmoothLoader{internal static MapLoaderContainer _last_action;}
public class LoadingScreen{public UnityEngine.Transform transform=new UnityEngine.Transform();public UnityEngine.UI.Text loadingHelperText=new UnityEngine.UI.Text(),percents;}
namespace UnityEngine{public enum RuntimePlatform{Android,LinuxPlayer}public class AndroidJavaObject:IDisposable{public T Call<T>(string name,params object[] args){return default(T);}public T Get<T>(string name){return default(T);}public void Dispose(){}}public class AndroidJavaClass:AndroidJavaObject{public AndroidJavaClass(string name){}public T GetStatic<T>(string name){return default(T);}}public enum LogType{Error,Assert,Warning,Log,Exception}public enum HorizontalWrapMode{Wrap}public enum VerticalWrapMode{Overflow}public enum TextAnchor{UpperLeft}public struct Color{public Color(float r,float g,float b,float a){}public static Color white;}public struct Vector2{public Vector2(float x,float y){}public static Vector2 zero;}public class Transform{public void SetParent(Transform t,bool b){}public void SetAsLastSibling(){}}public class RectTransform:Transform{public Vector2 anchorMin,anchorMax,offsetMin,offsetMax;}public class GameObject{public bool active;public void SetActive(bool b){active=b;}}public static class Application{public static RuntimePlatform platform=RuntimePlatform.LinuxPlayer;public static string persistentDataPath;public static event Action<string,string,LogType> logMessageReceived;public static int Subscribers{get{return logMessageReceived==null?0:logMessageReceived.GetInvocationList().Length;}}public static void Log(string message,LogType type){logMessageReceived?.Invoke(message,"trace",type);}}}
namespace UnityEngine.UI{public class Text{public UnityEngine.RectTransform rectTransform=new UnityEngine.RectTransform();public UnityEngine.GameObject gameObject=new UnityEngine.GameObject();public bool supportRichText;public UnityEngine.HorizontalWrapMode horizontalOverflow;public UnityEngine.VerticalWrapMode verticalOverflow;public UnityEngine.TextAnchor alignment;public int fontSize;public UnityEngine.Color color;public string text;}}
class BootDiagnosticsTests{static int count;static void Check(bool b,string label){if(!b)throw new Exception(label);count++;}static void Main(){var dir=Path.Combine(Path.GetTempPath(),"godworld-diagnostics-"+Guid.NewGuid());Directory.CreateDirectory(dir);UnityEngine.Application.persistentDataPath=dir;try{var screen=new LoadingScreen();BootDiagnostics.Begin(screen);BootDiagnostics.Begin(screen);Check(UnityEngine.Application.Subscribers==1,"one diagnostic subscription");SmoothLoader._last_action=new MapLoaderContainer{id="AssetManager.initLibs"};bool called=false;BootDiagnostics.Run(()=>called=true);Check(called,"successful native action executed once");var log=Path.Combine(dir,"godworld-startup.log");Check(File.ReadAllText(log).Contains("DONE AssetManager.initLibs"),"completed loader stage recorded");UnityEngine.Application.Log("warning",UnityEngine.LogType.Warning);BootDiagnostics.Paint(screen);Check(!screen.loadingHelperText.text.Contains("warning"),"warnings do not mask actual boot exceptions");SmoothLoader._last_action.id="Initialize weapons";bool threw=false;try{BootDiagnostics.Run(()=>throw new InvalidOperationException("actual startup fault"));}catch(InvalidOperationException){threw=true;}Check(threw,"native failure is rethrown, not skipped");Check(screen.loadingHelperText.text.Contains("Initialize weapons")&&screen.loadingHelperText.text.Contains("actual startup fault"),"failure and exact stage visible on loading page");Check(File.ReadAllText(log).Contains("FAILED Initialize weapons"),"full failure persisted locally");UnityEngine.Application.Log("secondary failure",UnityEngine.LogType.Error);BootDiagnostics.Paint(screen);Check(!screen.loadingHelperText.text.Contains("secondary failure"),"secondary errors do not replace primary diagnostic");Console.WriteLine(count+" boot diagnostic checks passed");}finally{Directory.Delete(dir,true);}}}
